// The dev server does not watch data/. The township files and the catalog are generated by
// `npm run fetch:township` (one file every few seconds while it runs). catalog.json is imported
// statically and the township files are globbed, so every write there made Vite reload the whole
// page. The URL hash (src/url-state.ts) now brings the open township and building back after a
// reload, but a reload for every file written is still noise. After a fetch finishes, restart
// `npm run dev` to pick up the new files.
export default {
  server: {
    watch: {
      ignored: ["**/data/**"],
    },
  },
};
